def solution(input_data):
    """
    Solves the apartment room rectangle problem.
    Input: string with grid dimensions and layout
    Output: string with grid after minimum wall removal
    """
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(lines[i + 1]) for i in range(n)]

    # Identify all free spaces and walls
    is_wall = [[grid[i][j] == '*' for j in range(m)] for i in range(n)]

    # Find connected components (rooms) of free spaces
    visited = [[False] * m for _ in range(n)]
    rooms = []

    def get_component_pos(i, j):
        """Find all positions in a connected component"""
        component = []
        queue = [(i, j)]
        visited[i][j] = True
        while queue:
            x, y = queue.pop(0)
            component.append((x, y))
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m:
                    if not visited[nx][ny] and not is_wall[nx][ny]:
                        visited[nx][ny] = True
                        queue.append((nx, ny))
        return component

    for i in range(n):
        for j in range(m):
            if not is_wall[i][j] and not visited[i][j]:
                component = get_component_pos(i, j)
                rooms.append(component)

    # For each connected component, find bounding box
    for room in rooms:
        min_r, max_r, min_c, max_c = float('inf'), float('inf'), float('inf'), float('inf')
        for r, c in room:
            min_r = min(min_r, r)
            max_r = max(max_r, r)
            min_c = min(min_c, c)
            max_c = max(max_c, c)
        # Fill the rectangle with free spaces
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if not is_wall[r][c]:
                    is_wall[r][c] = False
                else:
                    # We remove this wall
                    grid[r][c] = '.'

    return '\n'.join(''.join(row) for row in grid)


