# Solution for the lucky region problem

def is_lucky(n):
    """Check if a number is lucky (only contains digits 4 and 7)"""
    s = str(n)
    return all(c in '47' for c in s)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    n, m = map(int, lines[0].split())

    # Handle edge case where m=0 (no roads)
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        if i < len(lines) and lines[i]:
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components using BFS
    visited = [False] * (n + 1)
    components = []

    from collections import deque

    for i in range(1, n + 1):
        if not visited[i]:
            visited[i] = True
            size = 1
            queue = deque([i])
            while queue:
                curr = queue.popleft()
                for neighbor in adj[curr]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        size += 1
                        queue.append(neighbor)
            components.append(size)

    # Check if any component is already lucky
    for size in components:
        if is_lucky(size):
            return '0\n'

    # Generate all lucky numbers up to n
    lucky_numbers = []

    def generate_lucky(current):
        if current > n:
            return
        lucky_numbers.append(current)
        if current * 10 + 4 <= n:
            generate_lucky(current * 10 + 4)
        if current * 10 + 7 <= n:
            generate_lucky(current * 10 + 7)

    generate_lucky(4)
    lucky_numbers.sort(reverse=True)

    # For each lucky number, check if it can be formed and find minimum components needed
    min_components = float('inf')

    component_sum = sum(components)

    # Check if we can form each lucky number
    # Since we just need sum, we check if lucky number <= component_sum

    for target in lucky_numbers:
        if target > component_sum:
            continue

        # Use DP to find if target can be formed with minimum components
        # dp[v] = min components needed to get sum v
        dp = {}
        dp[0] = 0

        for size in components:
            new_dp = dp.copy()
            for prev_sum, count in dp.items():
                new_sum = prev_sum + size
                if new_sum <= target and new_sum in dp or new_sum == target:
                    if new_sum not in new_dp or new_dp[new_sum] > count + 1:
                        new_dp[new_sum] = count + 1

            dp.update(new_dp)

        if target in dp:
            min_components = min(min_components, dp[target])

    if min_components == float('inf'):
        return '-1\n'

    return f"{min_components - 1}\n"

