        path_set = {start}
        cycle = dfs_find_cycle(start, start, [start], path_set)

        if cycle:
            for v in cycle[:-1]:  # All vertices in cycle
                vertices_used.add(v)
            found_cycles.append(cycle)
        else:
            break

    # Output if we found k cycles
    if len(found_cycles) == k:
        result = ["CYCLES"]
        for cycle in found_cycles:
            result.append(str(len(cycle)))
            result.append(" ".join(map(str, cycle)))
        return "\n".join(result)

    # Otherwise, find path for Johnny with length >= ceil(n/k)
    target_len = (n + k - 1) // k
    if target_len < 1:
        target_len = 1

    # Find longest simple path
    def find_longest_path(start, path, path_set):
        """BFS-like search for long simple path."""
        stack = [(start, [start], {start})]
        best = None

        while stack:
            u, path, path_set_curr = stack[-1]

            if len(path) >= target_len + 5:  # Limit search depth
                if best is None or len(path) > len(best):
                    best = path
                stack.pop()
                continue

            for v in adj[u]:
                if v not in path_set_curr:
                    stack.append((v, path + [v], path_set_curr | {v}))

            if len(path) > target_len:
                stack.pop()
                continue

        return best

    best_path = None

    for start in range(1, n + 1):
        cand = find_longest_path(start, [start], {start})
        if cand and len(cand) >= target_len:
            if best_path is None or len(cand) >= len(best_path):
                best_path = cand
                if len(cand) >= target_len:
                    break

    if best_path and len(best_path) >= target_len:
        result = ["PATH"]
        result.append(str(len(best_path) - 1))
        result.append(" ".join(map(str, best_path)))
        return "\n".join(result)

    return "-1"


