def solution(input_data):
    parameters = input_data.strip().split()
    if len(parameters) != 3:
        return "-1"

    maxx = int(parameters[0])
    maxy = int(parameters[1])
    w = int(parameters[2])

    def rev(n):
        return int(str(n)[::-1])

    def is_lucky_pair(a, b):
        return a * b == rev(a) * rev(b)

    # Precompute all lucky ticket pairs (a, b) within limits
    lucky_pairs = set()
    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            if is_lucky_pair(a, b):
                lucky_pairs.add((a, b))

    total_lucky = len(lucky_pairs)

    if total_lucky < w:
        return "-1"

    # We need to find x, y such that count of (a, b) with 1 <= a <= x, 1 <= b <= y is >= w
    # and x*y is minimized

    # Build a 2D array counting lucky tickets
    count = [[0] * (maxy + 1) for _ in range(maxx + 1)]

    for a, b in lucky_pairs:
        count[a][b] = 1

    # Compute 2D prefix sums
    prefix = [[0] * (maxy + 1) for _ in range(maxx + 1)]
    for i in range(1, maxx + 1):
        for j in range(1, maxy + 1):
            prefix[i][j] = (count[i][j] + 
                           prefix[i-1][j] + 
                           prefix[i][j-1] - 
                           prefix[i-1][j-1])

    # Find x, y with prefix[x][y] >= w minimizing x*y
    best_x, best_y = maxx, maxy
    best_product = maxx * maxy

    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            if prefix[x][y] >= w:
                prod = x * y
                if prod < best_product:
                    best_product = prod
                    best_x, best_y = x, y
                elif prod == best_product and x < best_x:
                    best_x, best_y = x, y

    return f"{best_x} {best_y}"

