from math import gcd

def get_prime_factor_sum(d):
    """Returns sum of exponents in prime factorization of d"""
    temp = d
    count = 0
    p = 2
    while p * p <= temp:
        while temp % p == 0:
            count += 1
            temp //= p
        p += 1
    if temp > 1:
        count += 1
    return count

def get_divisors_greater_than_1(n):
    """Returns all divisors of n that are > 1"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i > 1:
                divisors.add(i)
            j = n // i
            if j > 1:
                divisors.add(j)
    return sorted(list(divisors))

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    idx = 1
    all_output = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1

        divisors = get_divisors_greater_than_1(n)

        # Output divisors sorted by prime factor sum (descending)
        divisors.sort(key=get_prime_factor_sum, reverse=True)
        divisor_output = " ".join(map(str, divisors))
        all_output.append(divisor_output)

        # Count coprime adjacent pairs in circular arrangement
        moves = 0
        for i in range(len(divisors)):
            a = divisors[i]
            b = divisors[(i + 1) % len(divisors)]
            if gcd(a, b) == 1:
                moves += 1

        all_output.append(str(moves))

    return "\n".join(all_output)
