def can_reach(n_adj, n, s, t, excluded):
    """Check if t is reachable from s with excluded edges."""
    visited = [False] * (n + 1)
    queue = [s]
    visited[s] = True
    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        if u == t:
            return True
        for v, edge_idx in n_adj[u]:
            if edge_idx not in excluded and not visited[v]:
                visited[v] = True
                queue.append(v)
    return False

def build_graph(n, m, edges):
    """Build adjacency list from edges. Edges use indices 0 to m-1."""
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v, w, _ = edges[i]
        adj[u].append((v, i))
        adj[v].append((u, i))
    return adj

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    # Parse edges
    edges = []
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        edges.append((parts[0], parts[1], parts[2], i + 1))  # store original index (1-based)

    # Build adjacency list
    adj = build_graph(n, m, edges)

    # Check if already disconnected
    if not can_reach(adj, n, s, t, set()):
        return "0\n0\n"

    best_val = float('inf')
    best_single = None
    best_pair = None

    # Check single edge removal
    for i in range(m):
        if not can_reach(adj, n, s, t, {i}):
            val = edges[i][2]
            if val < best_val:
                best_val = val
                best_single = (val, edges[i][3])  # store original index

    if best_single:
        return f"{best_single[0]}\n1\n{best_single[1]}"

    # Check pairs of edge removal
    for i in range(m):
        for j in range(i + 1, m):
            if not can_reach(adj, n, s, t, {i, j}):
                val = edges[i][2] + edges[j][2]
                if val < best_val:
                    best_val = val
                    best_pair = (val, edges[i][3], edges[j][3])

    if best_pair:
        return f"{best_pair[0]}\n2\n{best_pair[1]} {best_pair[2]}"
    else:
        return "-1"
