def solution(input_text):
    lines = input_text.strip().split('\n')
    n = int(lines[0].strip())

    # If n is odd, stable pairing is impossible (each city needs exactly one partner)
    if n % 2 != 0:
        return "-1\n"

    # Parse cost matrix
    # costs[i][j] = cost for city i to build rail to city j
    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        values = list(map(int, lines[i + 1].strip().split()))
        idx = 0
        for j in range(n):
            if i != j:
                costs[i][j] = values[idx]
                idx += 1

    # Build preference lists (lower cost = better preference)
    prefs = []
    for i in range(n):
        sorted_others = sorted(range(n), key=lambda x: costs[i][x])
        prefs.append(sorted_others)

    # Helper to get preference rank (lower = better)
    def get_rank(i, j):
        return prefs[i].index(j)

    # Check if a paired course is stable
    def is_stable(partners):
        if sum(1 for p in partners if p == -1) != 0:
            return False

        for i in range(n):
            partner_of_i = partners[i]
            if partner_of_i == -1:
                continue

            # Check all others i prefers over current partner
            for better in prefs[i]:
                if better == partner_of_i:
                    break

                # Who is better paired with
                partner_of_better = partners[better]
                if partner_of_better == -1:
                    continue

                # Better pairs with someone, check if better prefers i over their partner
                if get_rank(better, i) < get_rank(better, partner_of_better):
                    # Both i and better would prefer each other over current matches
                    return False

        return True

    # Generate all possible pairings
    def generate_pairings(cities):
        if not cities:
            yield []
            return

        first = cities[0]
        for i in range(1, len(cities)):
            second = cities[i]
            rest = cities[1:i] + cities[i+1:]
            for sub in generate_pairings(rest):
                yield [(first, second)] + sub

    # Try to find a stable pairing
    result = None
    for pairings in generate_pairings(list(range(n))):
        partners = [-1] * n
        for f, s in pairings:
            partners[f] = s
            partners[s] = f
        if is_stable(partners):
            result = partners
            break

    if result is None:
        return "-1\n"

    # Convert to 1-indexed output format
    output = []
    for i in range(n):
        output.append(str(result[i] + 1))

    return "\n".join(output) + "\n"
