    """Compute polynomial^n modulo mod using binary exponentiation."""
    result = {0: 1}  # 1 (x^0)
    base = poly.copy()

    while n > 0:
        if n & 1:
            result = poly_mul(result, base, mod, max_deg=200000)
        base = poly_mul(base, base, mod, max_deg=200000)
        n >>= 1

    return result

def poly_mul(p1, p2, mod, max_deg=200000):
    """Multiply two polynomials represented as dicts."""
    result = {}

