    # for each j, value[j] != a[j], where
    # value[j] = count of nodes in S that are either j or a neighbor of j
    # i.e., value[j] = x[j] + sum(x[k] for k in neighbors[j])

    # Greedy approach: Try selecting all nodes first
    # If that works, return all nodes
    # Otherwise, try removing nodes one by one

    def check(S: Set[int]) -> bool:
        for j in range(1, n + 1):
            value = 0
            if j in S:
                value += 1
            for neighbor in adj[j]:
                if neighbor in S:
                    value += 1
            if value == a[j]:
                return False
        return True

    # Try S = all nodes
    S_all = set(range(1, n + 1))
    if check(S_all):
        return str(n) + '\n' + ' '.join(map(str, sorted(S_all)))

    # Try removing one node at a time
    for remove_node in range(1, n + 1):
        S = S_all - {remove_node}
        if check(S):
            return str(len(S)) + '\n' + ' '.join(map(str, sorted(S)))

    # Try removing two nodes
    for remove1 in range(1, n + 1):
