            S = S_all - {remove1, remove2}
            if check(S):
                return str(len(S)) + '\n' + ' '.join(map(str, sorted(S)))

    # If we can't find a subset, try another approach
    # Select nodes greedily based on degree
    degrees = {i: len(adj[i]) for i in range(1, n + 1)}

    # Sort nodes by degree (ascending)
    nodes_sorted = sorted(range(1, n + 1), key=lambda x: (degrees[x], x))

    # Try sequential greedy approach
    current_S = set()
    for node in nodes_sorted:
        if node not in current_S:
            current_S.add(node)
            # Check if adding this node invalidates any counter
            valid = True
            for j in range(1, n + 1):
                value = 0
                if j in current_S:
                    value += 1
                for neighbor in adj[j]:
