            # Edges cross if one endpoint of second is between first's endpoints 
            # and the other is not, AND vice versa for first endpoints
            if b1 != b2:
                conflict_graph[i][j] = conflict_graph[j][i] = True

    # Check if conflict graph is bipartite using BFS/DFS 2-coloring
    color = [-1] * num_edges
    possible = True

