        for r in range(n):
            for c in range(m):
                time_at = r + c

                # Transformer exists only from time t onwards
                if time_at >= t:
                    cycle_idx = (time_at - t) % 4

                    # Get position at this cycle
                    px = x + (1 if cycle_idx >= 1 else 0) * d
                    py = y + (-1 if cycle_idx == 1 else 0) + (d if cycle_idx >= 2 else 0) + (-d if cycle_idx == 3 else 0)
                    py = y + (cycle_idx - 2 if cycle_idx >= 2 else 0) if cycle_idx != 1 else y - 1
                    if cycle_idx == 0:
