                        px, py = x + d, y - d
                    elif cycle_idx == 2:
                        px, py = x + d, y
                    elif cycle_idx == 3:
                        px, py = x, y + d

                    if px == r and py == c:
                        transformer_energy[r][c] += e

    # DP to find minimum energy
    INF = float('inf')
    dp = [[INF] * m for _ in range(n)]

    # Can only move from valid predecessor cells
    if 0 <= n and 0 <= m:
        dp[0][0] = transformer_energy[0][0]

    for i in range(n):
        for j in range(m):
            if dp[i][j] == INF:
                if i > 0 and dp[i-1][j] != INF:
                    dp[i][j] = min(dp[i][j], dp[i-1][j])
                if j > 0 and dp[i][j-1] != INF:
                    dp[i][j] = min(dp[i][j], dp[i][j-1])

    # Add energy for last cell if not set
    dp[n-1][m-1] += transformer_energy[n-1][m-1]

