                # Count (a, b) if both <= N
                if a <= N and b <= N:
                    valid_count += 1
                # Also count (b, a) if different from (a, b)
                if a != b and b <= N and a <= N:
                    valid_count += 1

    # Actually, let me recalculate valid_count more carefully
    valid_count = 0
    for a in range(1, N + 1):
