    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.length = len(s)

        def current(self):
            if self.pos < self.length:
                return self.s[self.pos]
            return ''

        def consume(self, c=None):
            if c is not None:
                assert self.current() == c, f"Expected '{c}', got '{self.current()}'"
            ch = self.current()
            self.pos += 1
            return ch

        def peek(self):
            return self.current()

        def skip_whitespace(self):
            while self.pos < self.length and self.current() == ' ':
                self.pos += 1

        # Return (value, length)
        def parse_expression(self):
            value, length = self.parse_term()

