                self.consume('+')
                skip_len, term_value = self.parse_term()
                if length >= 10 and value >= 0:
                    # We need to compute concatenation: value * 10^skip_len + term_value
                    value = (value * pow(10, skip_len, MOD) + term_value) % MOD
                else:
