# solution.py

def solve():
    """
    Problem: Count distinct decompositions of n into sum of distinct Fibonacci numbers.
    Fibonacci sequence: F1=1, F2=2, Fi = Fi-1 + Fi-2 for i>2
    """
    def generate_fibs(limit):
        """Generate Fibonacci numbers up to limit."""
        fibs = []
        a, b = 1, 2
        while a <= limit:
            fibs.append(a)
            a, b = b, a + b
        return fibs

    def memoize(f):
        cache = {}
        def wrapper(n):
            if n not in cache:
                cache[n] = f(n)
            return cache[n]
        return wrapper

    @memoize
    def count_decompositions(target, fibs):
        """Count ways to write target as sum of distinct Fibonacci numbers from fibs list."""
        if target == 0:
            return 1
        if len(fibs) == 0:
            return 0

        last_fib = fibs[-1]
        if last_fib > target:
            return count_decompositions(target, fibs[:-1])

        # Include last_fib
        count_include = count_decompositions(target - last_fib, fibs[:fibs.index(last_fib)])

        # Exclude last_fib
        count_exclude = count_decompositions(target, fibs[:-1])

        return count_include + count_exclude

    def get_anss(n_str):
        lines = n_str.strip().split('\n')
        if not lines or lines[0].strip() == '':
            return ''
        t = int(lines[0])
        results = []
        for i in range(1, t + 1):
            n = int(lines[i])

            # Generate Fibonacci numbers up to n
            fibs = generate_fibs(n)

            # For small n we can compute directly
            if n <= 1000000:
                result = count_decompositions(n, fibs)
            else:
                # Special handling: find Zeckendorf representation first
                # Then look for ways to modify it
                result = count_decompositions_n(n)
            results.append(str(result))
        return '\n'.join(results)

    def count_decompositions_n(n):
        """Count decompositions using optimized approach."""
        if n == 0:
            return 0

        fibs = generate_fibs(n)
        m = len(fibs)

        # Use optimized DP: at each step we either include or exclude the current Fibonacci
        # The key insight: we can process Fibonacci numbers from largest to smallest
        # and count combinations

        # For efficiency, use a simplified approach based on Zeckendorf properties
        # Initialize with the Zeckendorf-like representation

        # Actually, the most efficient way is to use the property that
        # there's a pattern: F_i + F_{i-1} = F_{i+1}
        # This allows replacing 2 consecutive Fibonacci numbers with 1 larger Fibonacci

        dp = {0: 1}
        for f in reversed(fibs):
            new_dp = dp.copy()
            for s, count in dp.items():
                if s + f <= n:
                    new_dp[s + f] = new_dp.get(s + f, 0) + count
            dp = new_dp

        return dp.get(n, 0)

def solution(input_str):
    return get_anss(input_str)
